   740    if (len < 0) mrb_raisef(mrb, E_INDEX_ERROR, "negative length (%i)", len);
   741
   742    /* range check */
   743    if (head < 0) {
   744      head += alen;
   745      if (head < 0) goto out_of_range;
   746    }
   747    if (head > ARY_MAX_SIZE - len) {
   748    out_of_range:
   749      mrb_raisef(mrb, E_INDEX_ERROR, "index %i is out of array", head);
   750    }
   751    tail = head + len;
   752    if (alen < len || alen < tail) {
   753      len = alen - head;
   754    }
   755
   756    /* size check */
   757    if (mrb_array_p(rpl)) {
   758      argc = RARRAY_LEN(rpl);
   759      argv = RARRAY_PTR(rpl);
   760      if (argv == ARY_PTR(a)) {
   761        struct RArray *r;
   762
   763        if (argc > 32767) {
