   765        }
   766        r = ary_dup(mrb, a);
   767        argv = ARY_PTR(r);
   768      }
   769    }
   770    else if (mrb_undef_p(rpl)) {
   771      argc = 0;
   772      argv = NULL;
   773    }
   774    else {
   775      argc = 1;
   776      argv = &rpl;
   777    }
